import React, { useEffect, useRef, useState } from 'react';
import './App.css';

type StepId = 'basic' | 'address' | 'company' | 'summary';

const TITLES: Record<StepId, string> = {
  basic: 'Basic info',
  address: 'Address',
  company: 'Company',
  summary: 'Summary'
};

// The required input ids on each step, in the order they appear.
const STEP_FIELDS: Record<StepId, string[]> = {
  basic: ['name', 'email'],
  address: ['street', 'city', 'country'],
  company: ['company-name'],
  summary: []
};

const EMPTY_FORM = {
  basic: { name: '', email: '' },
  address: { street: '', city: '', country: '', postalCode: '' },
  company: { isCompany: false, name: '' }
};

const isBlank = (value: string) => value.trim().length === 0;

export default function App() {
  // One form object, so moving between steps can never lose a value.
  const [form, setForm] = useState(EMPTY_FORM);
  const [stepId, setStepId] = useState<StepId>('basic');
  const [showErrors, setShowErrors] = useState(false);
  const [editing, setEditing] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const titleRef = useRef<HTMLHeadingElement>(null);
  const restartRef = useRef<HTMLButtonElement>(null);
  const isFirstRender = useRef(true);

  const { basic, address, company } = form;

  // Everything about the steps reads this list, so the company step needs no special cases.
  const steps: StepId[] = company.isCompany
    ? ['basic', 'address', 'company', 'summary']
    : ['basic', 'address', 'summary'];
  const stepIndex = steps.indexOf(stepId);

  const errors: Record<string, boolean> = {
    name: isBlank(basic.name),
    email: !/\S+@\S+\.\S+/.test(basic.email),
    street: isBlank(address.street),
    city: isBlank(address.city),
    country: isBlank(address.country),
    'company-name': isBlank(company.name)
  };
  const showError = (id: string) => showErrors && errors[id];

  useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    titleRef.current?.focus();
  }, [stepId]);

  useEffect(() => {
    if (submitted) restartRef.current?.focus();
  }, [submitted]);

  function update(section: 'basic' | 'address' | 'company', key: string, value: string | boolean) {
    setForm(prev => ({
      ...prev,
      [section]: { ...prev[section], [key]: value }
    }));
  }

  function next() {
    const invalid = STEP_FIELDS[stepId].filter(id => errors[id]);
    if (invalid.length > 0) {
      setShowErrors(true);
      document.getElementById(invalid[0])?.focus();
      return;
    }

    setShowErrors(false);
    if (!editing) {
      setStepId(steps[stepIndex + 1]);
      return;
    }

    // Turning on the company step while editing adds a field nobody has filled in yet.
    const unfinished = steps.find(step => STEP_FIELDS[step].some(id => errors[id]));
    if (!unfinished) setEditing(false);
    setStepId(unfinished ?? 'summary');
  }

  function prev() {
    setShowErrors(false);
    setEditing(false);
    setStepId(steps[stepIndex - 1]);
  }

  function edit(step: StepId) {
    setShowErrors(false);
    setEditing(true);
    setStepId(step);
  }

  function restart() {
    setForm(EMPTY_FORM);
    setStepId('basic');
    setShowErrors(false);
    setEditing(false);
    setSubmitted(false);
  }

  return (
    <main className="app">
      <section className="card">
        <header className="header">
          <h1>Multi-step Signup</h1>
          <p className="subtitle" aria-live="polite">Step {stepIndex + 1} of {steps.length}</p>
        </header>

        <section className="steps">
          <div className="step">
            <h2 ref={titleRef} className="step-title" tabIndex={-1}>{TITLES[stepId]}</h2>

            {stepId === 'basic' && (
              <div className="step-fields">
                <label className="field">
                  <span>Name</span>
                  <input
                    id="name"
                    type="text"
                    placeholder="Jane Doe"
                    value={basic.name}
                    onChange={e => update('basic', 'name', e.target.value)}
                    aria-invalid={showError('name') ? 'true' : undefined}
                  />
                  {showError('name') && <small className="error">Name is required.</small>}
                </label>

                <label className="field">
                  <span>Email</span>
                  <input
                    id="email"
                    type="email"
                    placeholder="jane@example.com"
                    value={basic.email}
                    onChange={e => update('basic', 'email', e.target.value)}
                    aria-invalid={showError('email') ? 'true' : undefined}
                  />
                  {showError('email') && <small className="error">Please enter a valid email.</small>}
                </label>

                <label className="company-toggle">
                  <input
                    className="is-company"
                    type="checkbox"
                    checked={company.isCompany}
                    onChange={e => update('company', 'isCompany', e.target.checked)}
                  />
                  <span>I am signing up for a company</span>
                </label>
              </div>
            )}

            {stepId === 'address' && (
              <div className="step-fields">
                <label className="field">
                  <span>Street</span>
                  <input
                    id="street"
                    type="text"
                    placeholder="123 Main St"
                    value={address.street}
                    onChange={e => update('address', 'street', e.target.value)}
                    aria-invalid={showError('street') ? 'true' : undefined}
                  />
                  {showError('street') && <small className="error">Street is required.</small>}
                </label>

                <label className="field">
                  <span>City</span>
                  <input
                    id="city"
                    type="text"
                    placeholder="Istanbul"
                    value={address.city}
                    onChange={e => update('address', 'city', e.target.value)}
                    aria-invalid={showError('city') ? 'true' : undefined}
                  />
                  {showError('city') && <small className="error">City is required.</small>}
                </label>

                <label className="field">
                  <span>Country</span>
                  <input
                    id="country"
                    type="text"
                    placeholder="Türkiye"
                    value={address.country}
                    onChange={e => update('address', 'country', e.target.value)}
                    aria-invalid={showError('country') ? 'true' : undefined}
                  />
                  {showError('country') && <small className="error">Country is required.</small>}
                </label>

                <label className="field">
                  <span>Postal code (optional)</span>
                  <input
                    id="postal-code"
                    type="text"
                    placeholder="34000"
                    value={address.postalCode}
                    onChange={e => update('address', 'postalCode', e.target.value)}
                  />
                </label>
              </div>
            )}

            {stepId === 'company' && (
              <div className="step-fields">
                <label className="field">
                  <span>Company name</span>
                  <input
                    id="company-name"
                    type="text"
                    placeholder="Acme"
                    value={company.name}
                    onChange={e => update('company', 'name', e.target.value)}
                    aria-invalid={showError('company-name') ? 'true' : undefined}
                  />
                  {showError('company-name') && <small className="error">Company name is required.</small>}
                </label>
              </div>
            )}

            {stepId === 'summary' && (
              <div className="summary">
                <div className="summary-heading">
                  <h3>Basic info</h3>
                  {!submitted && (
                    <button type="button" className="edit-basic" aria-label="Edit basic info" onClick={() => edit('basic')}>
                      Edit
                    </button>
                  )}
                </div>
                <p><strong>Name:</strong> {basic.name}</p>
                <p><strong>Email:</strong> {basic.email}</p>

                <div className="summary-heading">
                  <h3>Address</h3>
                  {!submitted && (
                    <button type="button" className="edit-address" aria-label="Edit address" onClick={() => edit('address')}>
                      Edit
                    </button>
                  )}
                </div>
                <p><strong>Street:</strong> {address.street}</p>
                <p><strong>City:</strong> {address.city}</p>
                <p><strong>Country:</strong> {address.country}</p>
                <p><strong>Postal code:</strong> {address.postalCode || '—'}</p>

                {company.isCompany && (
                  <>
                    <h3>Company</h3>
                    <p><strong>Company name:</strong> {company.name}</p>
                  </>
                )}
              </div>
            )}
          </div>
        </section>

        {submitted ? (
          <div className="done">
            <p className="success" role="status">Signup complete for {basic.name.trim()}.</p>
            <button ref={restartRef} type="button" className="restart" onClick={restart}>Start over</button>
          </div>
        ) : (
          <footer className="actions">
            <button type="button" className="ghost" onClick={prev} disabled={stepIndex === 0}>
              Back
            </button>

            {stepId !== 'summary' && (
              <button type="button" onClick={next}>
                {editing ? 'Save' : 'Next'}
              </button>
            )}

            {stepId === 'summary' && (
              <button type="button" className="primary" onClick={() => setSubmitted(true)}>
                Submit
              </button>
            )}
          </footer>
        )}
      </section>
    </main>
  );
}

